import {
  forwardRef,
  useId,
  useRef,
  type InputHTMLAttributes,
  type ReactNode,
} from "react";
import "./LayeredNumberField.css";

export type LayeredNumberFieldTone = "neutral" | "copper" | "green" | "gold";
export type LayeredNumberFieldSize = "small" | "medium" | "large";

export interface LayeredNumberFieldProps
  extends Omit<
    InputHTMLAttributes<HTMLInputElement>,
    "max" | "min" | "size" | "step" | "type"
  > {
  label: ReactNode;
  description?: ReactNode;
  error?: ReactNode;
  tone?: LayeredNumberFieldTone;
  numberFieldSize?: LayeredNumberFieldSize;
  fullWidth?: boolean;
  decrementLabel?: string;
  incrementLabel?: string;
  min?: number;
  max?: number;
  step?: number;
}

export const LayeredNumberField = forwardRef<
  HTMLInputElement,
  LayeredNumberFieldProps
>(function LayeredNumberField(
  {
    label,
    description,
    error,
    tone = "neutral",
    numberFieldSize = "medium",
    fullWidth = false,
    decrementLabel = "Decrease value",
    incrementLabel = "Increase value",
    className = "",
    id,
    disabled,
    readOnly,
    required,
    ...props
  },
  forwardedRef
) {
  const generatedId = useId();
  const inputRef = useRef<HTMLInputElement | null>(null);
  const inputId = id || `layered-number-field-${generatedId}`;
  const descriptionId = description ? `${inputId}-description` : undefined;
  const errorId = error ? `${inputId}-error` : undefined;

  const describedBy =
    [props["aria-describedby"], descriptionId, errorId]
      .filter(Boolean)
      .join(" ") || undefined;

  const isInvalid =
    Boolean(error) ||
    props["aria-invalid"] === true ||
    props["aria-invalid"] === "true";

  const wrapperClasses = [
    "layered-number-field",
    fullWidth ? "layered-number-field--full-width" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const setInputRef = (node: HTMLInputElement | null) => {
    inputRef.current = node;

    if (typeof forwardedRef === "function") {
      forwardedRef(node);
    } else if (forwardedRef) {
      forwardedRef.current = node;
    }
  };

  const stepValue = (direction: "up" | "down") => {
    const input = inputRef.current;

    if (!input || disabled || readOnly) {
      return;
    }

    if (direction === "up") {
      input.stepUp();
    } else {
      input.stepDown();
    }

    input.focus();
    input.dispatchEvent(new Event("input", { bubbles: true }));
  };

  return (
    <div
      className={wrapperClasses}
      data-tone={tone}
      data-size={numberFieldSize}
      data-disabled={disabled ? "true" : undefined}
      data-readonly={readOnly ? "true" : undefined}
      data-invalid={isInvalid ? "true" : undefined}
    >
      <label htmlFor={inputId} className="layered-number-field__label">
        {label}
        {required && (
          <span className="layered-number-field__required" aria-hidden="true">
            {" *"}
          </span>
        )}
      </label>

      <div className="layered-number-field__casing">
        <div className="layered-number-field__surface">
          <input
            {...props}
            ref={setInputRef}
            id={inputId}
            type="number"
            disabled={disabled}
            readOnly={readOnly}
            required={required}
            aria-describedby={describedBy}
            aria-invalid={isInvalid ? true : undefined}
            className="layered-number-field__control"
          />
        </div>

        <div className="layered-number-field__actuators">
          <button
            type="button"
            className="layered-number-field__actuator"
            aria-label={incrementLabel}
            disabled={disabled || readOnly}
            onClick={() => stepValue("up")}
          >
            <span aria-hidden="true">+</span>
          </button>
          <button
            type="button"
            className="layered-number-field__actuator"
            aria-label={decrementLabel}
            disabled={disabled || readOnly}
            onClick={() => stepValue("down")}
          >
            <span aria-hidden="true">−</span>
          </button>
        </div>
      </div>

      {description && (
        <div
          id={descriptionId}
          className="layered-number-field__description"
        >
          {description}
        </div>
      )}

      {error && (
        <div
          id={errorId}
          className="layered-number-field__error"
          role="alert"
        >
          {error}
        </div>
      )}
    </div>
  );
});

.layered-number-field {
    --number-field-tone-light: var(--tone-neutral-light);
    --number-field-tone-mid: var(--tone-neutral-mid);
    --number-field-tone-dark: var(--tone-neutral-dark);
    --number-field-tone-focus: var(--control-focus);
    --number-field-font-size: 0.95rem;
    --number-field-label-font-size: 0.875rem;
    --number-field-height: 44px;
    --number-field-padding-x: 14px;
    --number-field-actuator-width: 38px;

    display: inline-flex;
    flex-direction: column;
    gap: 6px;
    box-sizing: border-box;
    width: 100%;
    max-width: 320px;
    color: var(--color-text);
}

.layered-number-field--full-width {
    max-width: none;
}

.layered-number-field__label {
    color: var(--color-text);
    font-size: var(--number-field-label-font-size);
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: 0.015em;
    transition: color var(--duration-fast) var(--ease-control);
}

.layered-number-field__required {
    color: var(--number-field-tone-light);
}

.layered-number-field__casing {
    display: grid;
    grid-template-columns: minmax(0, 1fr) var(--number-field-actuator-width);
    gap: 3px;
    box-sizing: border-box;
    padding: 3px;
    border: 2px solid var(--control-shell-border);
    border-radius: var(--control-radius-outer);
    background: linear-gradient(180deg, var(--input-casing-top), var(--input-casing-bottom));
    box-shadow:
        0 2px 5px rgb(0 0 0 / 30%),
        inset 0 1px rgb(255 255 255 / 6%);
    transition:
        box-shadow var(--duration-fast) var(--ease-control),
        border-color var(--duration-fast) var(--ease-control);
}

.layered-number-field__surface {
    display: flex;
    align-items: center;
    min-width: 0;
    min-height: var(--number-field-height);
    overflow: hidden;
    border: 2px solid var(--control-trench);
    border-radius: var(--control-radius-inner);
    background: linear-gradient(180deg, var(--input-surface-bg-top), var(--input-surface-bg-bottom));
    box-shadow:
        inset 0 2px 4px rgb(0 0 0 / 50%),
        inset 0 -1px 1px rgb(255 255 255 / 3%);
    transition:
        border-color var(--duration-fast) var(--ease-control),
        box-shadow var(--duration-fast) var(--ease-control),
        background var(--duration-fast) var(--ease-control);
}

.layered-number-field__control {
    flex: 1 1 auto;
    min-width: 0;
    width: 100%;
    padding: 0 var(--number-field-padding-x);
    border: 0;
    outline: 0;
    appearance: textfield;
    background: transparent;
    color: var(--color-text);
    font-family: inherit;
    font-size: var(--number-field-font-size);
    font-variant-numeric: tabular-nums;
    line-height: 1.4;
}

.layered-number-field__control::-webkit-inner-spin-button,
.layered-number-field__control::-webkit-outer-spin-button {
    margin: 0;
    appearance: none;
}

.layered-number-field__control::placeholder {
    color: var(--color-text-muted);
    opacity: 0.65;
}

.layered-number-field__actuators {
    display: grid;
    grid-template-rows: repeat(2, minmax(0, 1fr));
    gap: 2px;
    min-height: var(--number-field-height);
}

.layered-number-field__actuator {
    display: grid;
    min-width: 0;
    min-height: 0;
    padding: 0;
    place-items: center;
    border: 1px solid var(--control-trench);
    border-radius: 3px;
    background:
        linear-gradient(180deg, rgb(255 255 255 / 10%), transparent 40%),
        linear-gradient(180deg, var(--number-field-tone-mid), var(--number-field-tone-dark));
    color: var(--tone-neutral-text);
    box-shadow:
        inset 0 1px rgb(255 255 255 / 16%),
        inset 0 -1px 1px rgb(0 0 0 / 34%);
    cursor: pointer;
    transition:
        filter var(--duration-fast) var(--ease-control),
        box-shadow var(--duration-fast) var(--ease-control),
        transform var(--duration-fast) var(--ease-control);
}

.layered-number-field__actuator span {
    font-size: 0.85rem;
    font-weight: 800;
    line-height: 1;
    transform: translateY(-0.5px);
}

.layered-number-field__actuator:hover:not(:disabled) {
    filter: brightness(1.1);
}

.layered-number-field__actuator:active:not(:disabled) {
    transform: translateY(1px);
    filter: brightness(0.82);
    box-shadow: inset 0 2px 3px rgb(0 0 0 / 44%);
}

.layered-number-field__actuator:focus-visible {
    outline: none;
    box-shadow:
        inset 0 0 0 2px var(--number-field-tone-focus),
        inset 0 -1px 1px rgb(0 0 0 / 34%);
}

.layered-number-field__description,
.layered-number-field__error {
    margin-top: 2px;
    font-size: 0.8rem;
    line-height: 1.4;
}

.layered-number-field__description {
    color: var(--color-text-muted);
}

.layered-number-field__error {
    color: var(--control-error-text, var(--control-error));
    font-weight: 500;
}

.layered-number-field[data-tone="copper"] {
    --number-field-tone-light: var(--tone-copper-light);
    --number-field-tone-mid: var(--tone-copper-mid);
    --number-field-tone-dark: var(--tone-copper-dark);
    --number-field-tone-focus: var(--tone-copper-light);
}

.layered-number-field[data-tone="green"] {
    --number-field-tone-light: var(--tone-green-light);
    --number-field-tone-mid: var(--tone-green-mid);
    --number-field-tone-dark: var(--tone-green-dark);
    --number-field-tone-focus: var(--tone-green-light);
}

.layered-number-field[data-tone="gold"] {
    --number-field-tone-light: var(--tone-gold-light);
    --number-field-tone-mid: var(--tone-gold-mid);
    --number-field-tone-dark: var(--tone-gold-dark);
    --number-field-tone-focus: var(--tone-gold-light);
}

.layered-number-field[data-size="small"] {
    --number-field-font-size: 0.85rem;
    --number-field-label-font-size: 0.8rem;
    --number-field-height: 36px;
    --number-field-padding-x: 10px;
    --number-field-actuator-width: 32px;
}

.layered-number-field[data-size="large"] {
    --number-field-font-size: 1.05rem;
    --number-field-label-font-size: 0.95rem;
    --number-field-height: 52px;
    --number-field-padding-x: 18px;
    --number-field-actuator-width: 44px;
}

.layered-number-field:not([data-disabled="true"]):not([data-readonly="true"]):hover .layered-number-field__casing {
    box-shadow:
        0 3px 8px rgb(0 0 0 / 40%),
        inset 0 1px rgb(255 255 255 / 9%);
}

.layered-number-field__surface:focus-within {
    border-color: var(--number-field-tone-focus);
    box-shadow:
        0 0 0 1px var(--number-field-tone-focus),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

.layered-number-field[data-disabled="true"] {
    opacity: 0.5;
    filter: grayscale(0.45);
    cursor: not-allowed;
}

.layered-number-field[data-disabled="true"] .layered-number-field__control,
.layered-number-field[data-disabled="true"] .layered-number-field__label,
.layered-number-field__actuator:disabled {
    cursor: not-allowed;
}

.layered-number-field[data-disabled="true"] .layered-number-field__surface {
    background: #141516;
}

.layered-number-field[data-readonly="true"] .layered-number-field__surface {
    border-color: #151617;
    background: #232426;
    box-shadow: inset 0 1px 2px rgb(0 0 0 / 30%);
}

.layered-number-field[data-readonly="true"] .layered-number-field__casing {
    background: linear-gradient(180deg, #3d3733, #2d2724);
    box-shadow: none;
}

.layered-number-field[data-readonly="true"] .layered-number-field__control {
    cursor: default;
}

.layered-number-field__actuator:disabled {
    filter: grayscale(0.5);
    opacity: 0.42;
}

.layered-number-field[data-invalid="true"] .layered-number-field__label {
    color: var(--control-error);
}

.layered-number-field[data-invalid="true"] .layered-number-field__surface,
.layered-number-field[data-invalid="true"] .layered-number-field__surface:focus-within {
    border-color: var(--control-error);
    box-shadow:
        0 0 0 1px var(--control-error),
        inset 0 2px 4px rgb(0 0 0 / 60%);
}

@media (max-width: 640px) {
    .layered-number-field {
        max-width: 100%;
    }
}

@media (forced-colors: active) {
    .layered-number-field__surface:focus-within {
        outline: 2px solid Highlight;
    }

    .layered-number-field__control,
    .layered-number-field__actuator {
        forced-color-adjust: auto;
    }

    .layered-number-field__actuator:focus-visible {
        outline: 2px solid Highlight;
        outline-offset: -3px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .layered-number-field__label,
    .layered-number-field__casing,
    .layered-number-field__surface,
    .layered-number-field__actuator {
        transition: none;
    }

    .layered-number-field__actuator:active:not(:disabled) {
        transform: none;
    }
}
